import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { Button } from '@linm-soft-org/linm-web-common-components';
import { scykRoutes } from '../../config/scykRoutes';
import { incidentPublicReportService } from '../../services/incidentPublicReports';
import type { IncidentPublicReport, IncidentPublicReportGuestInit } from '../../models/IncidentPublicReport';
import { utcToLocalInputValue } from '../../utils/dateTime';
import { getApiErrorMessage } from '../../utils/apiMessages';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { getOrCreatePublicDeviceId } from '../../utils/publicDeviceId';
import styles from '../IncidentPublicReportGuestPage/IncidentPublicReportGuestPage.module.css';

const IncidentPublicReportGuestViewPage: React.FC = () => {
  const { companyCode = '', id = '' } = useParams<{ companyCode: string; id: string }>();
  const appNavigate = useAppNavigate();
  const [init, setInit] = useState<IncidentPublicReportGuestInit | null>(null);
  const [item, setItem] = useState<IncidentPublicReport | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const L = (key: string) => init?.labels.find((o) => o.value === key)?.label ?? key;
  const statusLabel = (status: string) =>
    init?.statuses.find((o) => o.value === status)?.label ?? status;
  const kindLabel = (value: string) =>
    init?.reporterKinds.find((o) => o.value === value)?.label ?? value;
  const genderLabel = (value: string) =>
    init?.patientGenders.find((o) => o.value === value)?.label ?? value;

  useEffect(() => {
    getOrCreatePublicDeviceId();
  }, []);

  useEffect(() => {
    let cancelled = false;
    const t = setTimeout(() => {
      Promise.all([
        incidentPublicReportService.guestInit(companyCode),
        incidentPublicReportService.mineById(companyCode, id),
      ])
        .then(([initData, report]) => {
          if (cancelled) return;
          setInit(initData);
          setItem(report);
        })
        .catch((err) => { if (!cancelled) setError(getApiErrorMessage(err)); })
        .finally(() => { if (!cancelled) setLoading(false); });
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  }, [companyCode, id]);

  if (loading) {
    return <div className={styles.loadingWrap}><i className="fas fa-spinner fa-spin" /> {L('loading')}</div>;
  }

  return (
    <div className={styles.page} data-testid="incident-public-report-guest-view">
      <div className={styles.header}>
        <div className={styles.brand}>
          <h1>{L('guestViewTitle')}</h1>
          <p>{item?.idCode} · {item ? statusLabel(item.status) : ''}</p>
        </div>
      </div>
      <div className={styles.formBody}>
        {error && <div className={styles.errorBanner}>{error}</div>}
        {item && (
          <div className={styles.section}>
            <div className={styles.row}>
              <div className={styles.field}><label>{L('reporterKind')}</label><input readOnly value={kindLabel(item.reporterKind)} /></div>
              <div className={styles.field}><label>{L('reporterName')}</label><input readOnly value={item.reporterName} /></div>
            </div>
            <div className={styles.row}>
              <div className={styles.field}><label>{L('patientName')}</label><input readOnly value={item.patientName} /></div>
              <div className={styles.field}><label>{L('reporterPhone')}</label><input readOnly value={item.reporterPhone} /></div>
            </div>
            <div className={styles.row}>
              <div className={styles.field}><label>{L('patientGender')}</label><input readOnly value={genderLabel(item.patientGender)} /></div>
              <div className={styles.field}><label>{L('idCode')}</label><input readOnly value={item.idCode} /></div>
            </div>
            <div className={styles.row}>
              <div className={styles.field}><label>{L('department')}</label><input readOnly value={item.departmentName} /></div>
              <div className={styles.field}><label>{L('areaText')}</label><input readOnly value={item.areaText ?? ''} /></div>
            </div>
            <div className={styles.field}>
              <label>{L('occurredAt')}</label>
              <input readOnly value={utcToLocalInputValue(item.occurredAt)} />
            </div>
            <div className={styles.field}>
              <label>{L('description')}</label>
              <textarea readOnly rows={4} value={item.description} />
            </div>
            {item.rejectReason && (
              <div className={styles.field}>
                <label>{L('rejectReason')}</label>
                <textarea readOnly rows={2} value={item.rejectReason} />
              </div>
            )}
            {item.incidentIdCode && (
              <div className={styles.field}>
                <label>{L('incidentCode')}</label>
                <input readOnly value={item.incidentIdCode} />
              </div>
            )}
          </div>
        )}
        <div className={styles.actions}>
          <Button variant="secondary" onClick={() => appNavigate(scykRoutes.publicReports.guestHistory(companyCode))}>
            {L('back')}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default IncidentPublicReportGuestViewPage;
